import { PlayerId } from "@bloxd"
import { BaseMapInfo, BaseTeamInfo } from "./types"
import { SessionBasedPlayer } from "./SessionBasedPlayer"
import { shuffleArray, getRandomItem, setTimeout } from "@plugins/helpers"

const MAP_VOTING_CATEGORY = "__SBG_MAP_VOTING__"
const MAP_VOTING_ITEM_PREFIX = "__SBG_MAP_"

const MAP_OPTION_COUNT = 4

export class MapVoter<TeamInfo extends BaseTeamInfo, MapInfo extends BaseMapInfo<TeamInfo>> {
	private possibleMapOptions: MapInfo[] = []
	private mapVotes: Record<PlayerId, MapInfo["name"]> = {}
	private mapVotingActive: boolean = false

	constructor(
		readonly maps: readonly MapInfo[],
		readonly players: Record<PlayerId, SessionBasedPlayer<TeamInfo, MapInfo>>,
	) {}

	createMapVoting(): void {
		if (this.mapVotingActive) {
			return
		}
		this.mapVotingActive = true
		api.configureShopCategory(MAP_VOTING_CATEGORY, {
			customTitle: "Map Voting",
			sortPriority: 0.5,
		})

		// Delete previous map options
		for (const map of this.possibleMapOptions) {
			api.deleteShopItem(MAP_VOTING_CATEGORY, `${MAP_VOTING_ITEM_PREFIX}${map.name}`)
		}

		const possibleOptions = this.maps.slice()
		shuffleArray(possibleOptions)
		this.possibleMapOptions = possibleOptions.slice(0, MAP_OPTION_COUNT)
		for (const map of this.possibleMapOptions) {
			api.createShopItem(MAP_VOTING_CATEGORY, `${MAP_VOTING_ITEM_PREFIX}${map.name}`, {
				image: map.icon,
				customTitle: map.name,
				canBuy: true,
				buyButtonText: "Votes: 0",
			})
		}

		setTimeout(() => {
			for (const playerId in this.players) {
				api.openShop(playerId, false, MAP_VOTING_CATEGORY)
			}
		}, 100)
	}

	onMapVote(playerId: PlayerId, categoryKey: string, shopItemKey: string) {
		if (categoryKey !== MAP_VOTING_CATEGORY) {
			return
		}
		if (!this.mapVotingActive) {
			return
		}
		if (!shopItemKey.startsWith(MAP_VOTING_ITEM_PREFIX)) {
			return
		}
		const mapName = shopItemKey.replace(MAP_VOTING_ITEM_PREFIX, "")
		if (
			!this.possibleMapOptions.some((map) => {
				return map.name === mapName
			})
		) {
			return
		}
		const hadVotedBefore = !!this.mapVotes[playerId]
		this.mapVotes[playerId] = mapName
		this.updateMapVotingForPlayer(playerId)
		this.updateMapCountsForEveryone()
		if (!hadVotedBefore) {
			api.openShop(playerId, true)
		}
	}

	onPlayerJoin(playerId: PlayerId) {
		if (!this.mapVotingActive) {
			return
		}
		this.updateMapVotingForPlayer(playerId)
		setTimeout(
			() => {
				api.openShop(playerId, false, MAP_VOTING_CATEGORY)
			},
			100,
			playerId,
		)
	}

	onPlayerLeave(playerId: PlayerId) {
		if (!this.mapVotingActive) {
			return
		}
		delete this.mapVotes[playerId]
		this.updateMapCountsForEveryone()
	}

	private updateMapCountsForEveryone() {
		for (const map of this.possibleMapOptions) {
			const votes = Object.values(this.mapVotes).filter((v) => {
				return v === map.name
			}).length
			api.updateShopItem(MAP_VOTING_CATEGORY, `${MAP_VOTING_ITEM_PREFIX}${map.name}`, {
				buyButtonText: `Votes: ${votes}`,
			})
		}
	}
	private updateMapVotingForPlayer(playerId: PlayerId) {
		api.configureShopCategoryForPlayer(playerId, MAP_VOTING_CATEGORY, {
			redDot: !this.mapVotes[playerId],
		})
		for (const map of this.possibleMapOptions) {
			api.updateShopItemForPlayer(playerId, MAP_VOTING_CATEGORY, `${MAP_VOTING_ITEM_PREFIX}${map.name}`, {
				canBuy: this.mapVotes[playerId] !== map.name,
				isSelected: this.mapVotes[playerId] === map.name,
			})
		}
	}

	endMapVoting() {
		if (!this.mapVotingActive) {
			return
		}
		this.mapVotingActive = false
		for (const map of this.possibleMapOptions) {
			api.deleteShopItem(MAP_VOTING_CATEGORY, `${MAP_VOTING_ITEM_PREFIX}${map.name}`)
		}
		this.possibleMapOptions = []
		this.mapVotes = {}
	}

	chooseMap(): MapInfo {
		if (!this.mapVotingActive) {
			return null
		}
		const votedPlayers = Object.keys(this.mapVotes)
		if (votedPlayers.length === 0) {
			return getRandomItem(this.possibleMapOptions)
		}

		const randomPlayer = getRandomItem(votedPlayers)
		const choice = this.mapVotes[randomPlayer]
		return this.maps.find((map) => {
			return map.name === choice
		})
	}
}
